import java.time.*;
import java.time.format.DateTimeFormatter;
import java.time.temporal.ChronoUnit;

public class Main {
    static final String[] HARI = {"Senin", "Selasa", "Rabu", "Kamis", "Jumat", "Sabtu", "Minggu"};
    static final DateTimeFormatter TGL = DateTimeFormatter.ofPattern("dd/MM/yyyy");

    public static void main(String[] args) {
        LocalDate hariIni = LocalDate.of(2026, 10, 30);
        String[] pelanggan = {"Sari", "Andi", "Toko Maju"};
        LocalDate[] kirim = {
                LocalDate.of(2026, 10, 20),
                LocalDate.of(2026, 10, 16),
                LocalDate.of(2026, 10, 1)};

        for (int i = 0; i < pelanggan.length; i++) {
            LocalDate jatuhTempo = kirim[i].plusDays(14);
            String hari = HARI[jatuhTempo.getDayOfWeek().getValue() - 1];
            String status;
            if (hariIni.isAfter(jatuhTempo)) {
                long telat = ChronoUnit.DAYS.between(jatuhTempo, hariIni);
                status = "terlambat " + telat + " hari, denda Rp" + (telat * 2000);
            } else if (hariIni.isEqual(jatuhTempo)) {
                status = "jatuh tempo hari ini";
            } else {
                status = "aman";
            }
            System.out.println(pelanggan[i] + " | " + hari + " " + jatuhTempo.format(TGL) + " | " + status);
        }
    }
}

